def log(msg):
    print("[study] %s" % msg, flush=True)


def run(cmd, timeout=None):
    """Run a step, echo its output, return the exit code."""
    log("$ " + " ".join(cmd))
    proc = subprocess.run(cmd, cwd=ROOT, text=True, timeout=timeout)
    if proc.returncode != 0:
        log("!! step failed with code %d: %s" % (proc.returncode, " ".join(cmd)))
    return proc.returncode


def maybe_hf_login():
    """Log in to HuggingFace if a token is available, for gated models.

    Kaggle script kernels have no CLI login; the token can come from an env var
    or from Kaggle -> Add-ons -> Secrets (name HF_TOKEN). Without one, gated
    repos such as meta-llama/Llama-3.2-3B-Instruct return 401.
    """
    token = os.environ.get("HF_TOKEN") or os.environ.get("HUGGING_FACE_HUB_TOKEN")
    if not token:
        try:
            from kaggle_secrets import UserSecretClient
            token = UserSecretClient().get_secret("HF_TOKEN")
        except Exception:
            token = None
    if not token:
        log("no HF_TOKEN - gated models (llama3.2-3b) will fail with 401")
        return False
    try:
        from huggingface_hub import login
        login(token=token)
        log("HF token accepted - gated models available")
        return True
    except Exception as exc:
        log("HF login failed: %s" % exc)
        return False


def ensure_model_stack():
    """torch/transformers are preinstalled on Kaggle but versions drift."""
    if os.environ.get("SLM_SKIP_DEPS") == "1" or os.environ.get("SHIM_MODE") == "mock":
        log("dependency install skipped (mock / SLM_SKIP_DEPS=1)")
        return
    try:
        import transformers
        major, minor = (int(x) for x in transformers.__version__.split(".")[:2])
        ok = (major, minor) >= (4, 40)
        log("transformers %s (%s)" % (transformers.__version__,
                                      "ok" if ok else "too old for chat pipelines"))
    except Exception as exc:
        log("transformers missing: %s" % exc)
        ok = False
    if not ok:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-U",
                        "transformers>=4.44", "accelerate>=0.30"], check=False)
    try:
        import torch
        log("torch %s cuda=%s devices=%d" % (torch.__version__, torch.cuda.is_available(),
                                            torch.cuda.device_count()))
        if torch.cuda.is_available():
            log("gpu: %s" % torch.cuda.get_device_name(0))
    except Exception as exc:
        log("torch missing: %s" % exc)
    ensure_wordnet()


def ensure_wordnet():
    """nltk + the WordNet corpus, for the saliency attack's candidate set.

    Installed here rather than imported lazily inside the attack because a
    corpus download mid-run would show up as a mysterious per-sample stall. If
    it fails the saliency attack still runs on the curated lexicon alone - the
    coverage drop is logged so the report can say which candidate set was used.
    """
    try:
        import nltk
    except ModuleNotFoundError:
        log("installing nltk for the saliency attack")
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "nltk"],
                       check=False)
    try:
        import nltk
        for pkg in ("wordnet", "omw-1.4"):
            nltk.download(pkg, quiet=True)
        from nltk.corpus import wordnet as wn
        log("wordnet ready (%d synsets for 'account')" % len(wn.synsets("account")))
    except Exception as exc:
        log("!! wordnet unavailable: %s - saliency attack falls back to the "
            "curated lexicon only" % exc)


def start_shim():
    if os.name == "posix":
        subprocess.run("fuser -k %d/tcp" % PORT, shell=True, capture_output=True)
    logf = open(os.path.join(ROOT, "shim.log"), "wb")
    shim_env = dict(os.environ, PORT=str(PORT))
    shim_env.setdefault("SHIM_MODE", "real")
    proc = subprocess.Popen([sys.executable, "src/shim_colab.py"], cwd=ROOT,
                            env=shim_env, stdout=logf, stderr=subprocess.STDOUT,
                            start_new_session=True)
    log("shim pid=%d" % proc.pid)
    deadline = time.time() + 300
    while time.time() < deadline:
        try:
            with urllib.request.urlopen("http://localhost:%d/health" % PORT, timeout=3) as r:
                health = json.load(r)
            log("shim up: %s" % health)
            return proc
        except Exception:
            if proc.poll() is not None:
                log("shim exited early (%s)" % proc.returncode)
                break
            time.sleep(3)
    log("!! shim did not become healthy")
    return proc


def shim_tail(lines=40):
    path = os.path.join(ROOT, "shim.log")
    if os.path.exists(path):
        tail = open(path, errors="replace").read().strip().splitlines()[-lines:]
        log("--- shim.log tail ---")
        for line in tail:
            log("  " + line)


def probe():
    """Three controlled messages: catches a degenerate model before any F1."""
    sys.path.insert(0, ROOT)
    from src.common import MODELS as MODEL_IDS
    from src.prompting import build_messages

    # MODELS holds short keys ('qwen2.5-3b'); the shim needs the HF id, otherwise
    # transformers says "not a valid model identifier" and it looks like a bug.
    model_id = MODEL_IDS.get(MODELS[0], MODELS[0])
    log("probe model: %s" % model_id)

    def ask(text, timeout=900):          # first call loads the model into VRAM
        payload = json.dumps({"model": model_id, "messages": build_messages("sms_smishing", text),
                              "temperature": 0.0, "max_tokens": 8, "seed": 42}).encode()
        req = urllib.request.Request(BASE_URL + "/chat/completions", data=payload,
                                     headers={"Content-Type": "application/json"})
        t0 = time.time()
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                out = json.load(r)
        except urllib.error.HTTPError as exc:
            # the shim puts the real reason in the body; without this the kernel
            # only ever showed "HTTP Error 500" and hid the cause
            body = exc.read().decode("utf-8", "replace")[:800]
            raise RuntimeError(f"model server returned {exc.code}: {body}")
        return (out["choices"][0]["message"]["content"],
                out.get("shim", {}).get("parsed_verdict"), time.time() - t0)

    cases = [("benign   ", "Hey, are we still meeting at 5?"),
             ("malicious", "Your parcel is held at customs. Pay Rs 200 at http://bit.ly/pay2win"),
             ("benign   ", "ok thanks, see you tomorrow")]
    preds = []
    for label, text in cases:
        raw, pred, dt = ask(text)
        preds.append(pred)
        log("probe %s %6.1fs raw=%r parsed=%s" % (label, dt, raw, pred))
    if None in preds:
        log("!! probe verdicts did not parse")
    elif len(set(preds)) == 1:
        log("!! CONSTANT PREDICTION in probe - model is not discriminating")
    else:
        log("probe OK - model separates benign from malicious")
    return preds


def main():
    started = time.time()
    log("root=%s models=%s limit=%s" % (ROOT, MODELS, LIMIT or "full"))
    rc_boot = BOOTSTRAP_RC
    log("bootstrap rc=%s" % rc_boot)

    ensure_model_stack()
    maybe_hf_login()
    shim_proc = start_shim()
    try:
        try:
            probe()
        except Exception as exc:
            log("!! probe failed: %s" % exc)
            shim_tail()
            raise
        for model in MODELS:
            cmd = [sys.executable, "src/run_baseline.py", "--model", model,
                   "--base-url", BASE_URL]
            if LIMIT:
                cmd += ["--limit", LIMIT]
            run(cmd)
        run([sys.executable, "src/summarize_baseline.py"])
        run([sys.executable, "src/analyze_baseline.py"])
        # ── attack phase ──────────────────────────────────────────────────
        # The attack set is built for EVERY model x task the clean models
        # actually caught, then each model is attacked in both modes. The set
        # must exist first: without it there is no denominator, and an ASR
        # computed anyway would be meaningless.
        rc_set = run([sys.executable, "src/build_attack_set.py", "--all-models"])
        if rc_set != 0:
            log("!! no attack set - skipping the attack phase (report will say so)")
        else:
            for model in MODELS:
                for mode in ATTACK_MODES:
                    run([sys.executable, "src/run_attack.py",
                         "--model", model, "--mode", mode,
                         "--attempts", str(ATTACK_ATTEMPTS),
                         "--base-url", BASE_URL])
            # one table for the paper, recomputed from the per-sample CSVs
            run([sys.executable, "src/summarize_attack.py"])
            # paired comparison of the two modes on the shared messages: this is
            # ── saliency (PWWS-style) word attack ────────────────────────
            # A separate attack, not a better random search: it needs the shim's
            # probability endpoint and ranks substitutions by measured saliency.
            if os.environ.get("SLM_SALIENCY", "1") == "1":
                for model in MODELS:
                    rc_sal = run([sys.executable, "src/run_saliency.py",
                                  "--model", model, "--base-url", BASE_URL])
                    if rc_sal != 0:
                        log("!! saliency attack on %s failed (rc=%s)" % (model, rc_sal))
                # The saliency attack decides success on P(malicious) < 0.5 while
                # every other mode uses the generated verdict. Re-read every
                # stored row through the generation route so the three ASRs in
                # the table are measured with the same ruler.
                if os.environ.get("SLM_VERIFY", "1") == "1":
                    rc_ver = run([sys.executable, "src/verify_saliency.py",
                                  "--base-url", BASE_URL])
                    if rc_ver != 0:
                        log("!! saliency verification failed (rc=%s) - the table "
                            "will fall back to the probability channel" % rc_ver)
                else:
                    log("saliency verification skipped (SLM_VERIFY=0)")
                run([sys.executable, "src/summarize_attack.py"])
            else:
                log("saliency phase skipped (SLM_SALIENCY=0)")
            # ── matched-vocabulary / matched-budget ablation ──────────────
            # Five arms over ONE candidate set, ONE probe phase and ONE query
            # cap, so the ordering, candidate-set and oracle effects stop being
            # tangled (paper Section 6.5). Each arm writes its own CSV the
            # moment it finishes, so a session that runs out of time keeps
            # every completed cell instead of losing the whole phase.
            if os.environ.get("SLM_ABLATION", "1") == "1":
                arms = [a for a in os.environ.get(
                    "SLM_ABLATION_ARMS",
                    "random-prob,saliency-prob,random-verdict,group-verdict,"
                    "textfooler-prob").split(",") if a]
                abl_models = [m for m in os.environ.get(
                    "SLM_ABLATION_MODELS", ",".join(MODELS)).split(",") if m]
                qcap = os.environ.get("SLM_ABLATION_QUERY_CAP", "24")
                abl_limit = os.environ.get("SLM_ABLATION_LIMIT", "400")
                log("ablation: %d arm(s) x %d model(s), %s calls/message max, "
                    "first %s messages" % (len(arms), len(abl_models), qcap,
                                           abl_limit or "all"))
                for model in abl_models:
                    for arm in arms:
                        cmd = [sys.executable, "src/run_ablation.py",
                               "--model", model, "--arm", arm,
                               "--base-url", BASE_URL, "--query-cap", qcap]
                        if abl_limit:
                            cmd += ["--limit", abl_limit]
                        rc_ab = run(cmd)
                        if rc_ab != 0:
                            log("!! ablation arm %s on %s failed (rc=%s)"
                                % (arm, model, rc_ab))
                # The candidate-set contrast needs the SAME arm over the small
                # hand-written table: one more arm at one more vocabulary.
                for model in abl_models:
                    cmd = [sys.executable, "src/run_ablation.py",
                           "--model", model, "--arm", "random-verdict",
                           "--vocab", "small_table",
                           "--base-url", BASE_URL, "--query-cap", qcap]
                    if abl_limit:
                        cmd += ["--limit", abl_limit]
                    rc_cv = run(cmd)
                    if rc_cv != 0:
                        log("!! candidate-set arm on %s failed (rc=%s)"
                            % (model, rc_cv))
                rc_sum_ab = run([sys.executable, "src/summarize_ablation.py"])
                if rc_sum_ab != 0:
                    log("!! ablation summary failed (rc=%s) - the arm CSVs are "
                        "intact, rebuild the tables locally" % rc_sum_ab)
            else:
                log("ablation phase skipped (SLM_ABLATION=0)")
            # ── paired mode comparison ───────────────────────────────────
            # AFTER the saliency phase on purpose: the pairing needs all three
            # modes, and running it earlier silently produced a two-mode table.
            # the claim the paper makes, so it is recomputed, not hand-derived
            run([sys.executable, "src/analyze_pairs.py"])
            # ── cross-model transfer ──────────────────────────────────────
            # Replays the stored perturbed texts on every other model. No new
            # attack is generated; the denominator is what the TARGET caught on
            # the original text (see src/transfer_common.py). Also placed after
            # the saliency phase, for the same reason: transfer of saliency
            # perturbations cannot be measured before they exist.
            if os.environ.get("SLM_TRANSFER", "1") == "1":
                for model in MODELS:
                    # --include-self replays the model's OWN perturbations too.
                    # That replay must reproduce the single-model ASR exactly
                    # (same texts, same prompt, deterministic decode), so it is
                    # the only check that says the replay path is faithful.
                    # It costs one extra pass per model.
                    rc_tr = run([sys.executable, "src/run_transfer.py",
                                 "--target", model, "--base-url", BASE_URL,
                                 "--include-self"])
                    if rc_tr != 0:
                        log("!! transfer onto %s failed (rc=%s) - matrix will be "
                            "partial" % (model, rc_tr))
                rc_st = run([sys.executable, "src/summarize_transfer.py"])
                if rc_st != 0:
                    log("!! transfer self-replay did NOT reproduce the single-model "
                        "ASR (rc=%s) - every off-diagonal cell is suspect" % rc_st)
            else:
                log("transfer phase skipped (SLM_TRANSFER=0)")
            # ── training-free defences ───────────────────────────────────
            # Re-scores the SAME stored perturbations under input normalisation
            # and a matched-FPR threshold, so nothing here is a new attack.
            if os.environ.get("SLM_DEFENSE", "1") == "1":
                for model in MODELS:
                    rc_def = run([sys.executable, "src/run_defense.py",
                                  "--model", model, "--base-url", BASE_URL])
                    if rc_def != 0:
                        log("!! defence probe on %s failed (rc=%s)" % (model, rc_def))

            else:
                log("defence phase skipped (SLM_DEFENSE=0)")
    finally:
        # always release the GPU/port: a leaked shim makes the next run look dead
        if shim_proc is not None and shim_proc.poll() is None:
            shim_proc.terminate()
            try:
                shim_proc.wait(timeout=15)
            except Exception:
                shim_proc.kill()
            log("shim stopped")
        if os.name == "posix":
            subprocess.run("fuser -k %d/tcp" % PORT, shell=True, capture_output=True)

    # A reporting bug must not turn a finished 40-minute run into ERROR: the
    # measurements are already in results/, and REPORT.md is only a summary.
    try:
        write_report(started)
    except Exception as exc:
        import traceback
        log("!! REPORT.md failed: %s: %s" % (type(exc).__name__, exc))
        traceback.print_exc()
        log("   results/ is intact - rebuild the report locally instead")
    log("done in %.1f min" % ((time.time() - started) / 60.0))


def write_report(started):
    """Human-readable summary that travels back with the kernel output."""
    import pandas as pd

    lines = ["# Kaggle run report", "",
             "models: `%s`" % ", ".join(MODELS),
             "limit: %s" % (LIMIT or "full eval set"),
             "runtime: %.1f min" % ((time.time() - started) / 60.0), ""]
    shim_log = os.path.join(ROOT, "shim.log")
    if os.path.exists(shim_log):
        tail = open(shim_log, errors="replace").read().strip().splitlines()[-6:]
        lines += ["## shim.log tail", "```"] + tail + ["```", ""]

    csv_path = os.path.join(ROOT, "results", "clean_baseline_results.csv")
    if os.path.exists(csv_path):
        df = pd.read_csv(csv_path)
        table = []
        for (model, task), g in df.groupby(["model", "task"]):
            pred = g["pred"]
            tp = int(((g.ground_truth == 1) & (pred == 1)).sum())
            fp = int(((g.ground_truth == 0) & (pred == 1)).sum())
            tn = int(((g.ground_truth == 0) & (pred == 0)).sum())
            fn = int(((g.ground_truth == 1) & (pred == 0)).sum())
            acc = (tp + tn) / max(len(g), 1)
            prec = tp / max(tp + fp, 1)
            rec = tp / max(tp + fn, 1)
            f1 = 2 * prec * rec / max(prec + rec, 1e-9)
            table.append("| %s | %s | %d | %d | %d | %d | %.4f | %.4f | %.4f | %.4f | %d |"
                         % (model, task, tp, fp, tn, fn, acc, prec, rec, f1,
                            int(g["pred"].isna().sum())))
        lines += ["## baseline", "",
                  "| model | task | tp | fp | tn | fn | acc | prec | rec | f1 | unparsed |",
                  "|---|---|---|---|---|---|---|---|---|---|---|"] + table + [""]
    # ── attack: table computed from the per-sample CSVs, not from prose ──
    import glob
    lines += ["## attack", ""]
    attack_csvs = sorted(glob.glob(os.path.join(ROOT, "results", "attack_results_*.csv")))
    if not attack_csvs:
        lines += ["no attack results: the attack phase did not run (build_attack_set "
                  "or run_attack failed - see the log above).", ""]
    else:
        lines += ["ASR = malicious->benign flips / samples actually attacked. "
                  "Only rows the clean model re-confirmed as malicious are counted. "
                  "CI = 95% Wilson interval on the flip count.",
                  "| model | mode | task | attacked | flips | ASR | 95% CI | mean perturb | mean Jaccard |",
                  "|---|---|---|---|---|---|---|---|---|"]
        from src.attack_common import asr_interval, read_attack_csv
        for path in attack_csvs:
            a = read_attack_csv(path)
            if "counted" not in a.columns:
                continue
            counted = a[a["counted"] == True]        # noqa: E712
            vcol = "success_gen" if "success_gen" in a.columns else "success"
            if vcol != "success":
                counted = counted[counted[vcol].notna()]
            for (model, mode, task), g in counted.groupby(["model", "mode", "task"]):
                flags = [bool(x) for x in g[vcol]]
                flips = int(sum(flags))
                ci = asr_interval(flags)
                lines.append("| %s | %s | %s | %d | %d | %.1f%% | %.1f-%.1f%% | %.1f%% | %.3f |"
                             % (model, mode, task, len(g), flips,
                                100.0 * flips / max(len(g), 1),
                                100.0 * ci["wilson_low"], 100.0 * ci["wilson_high"],
                                100.0 * float(g["perturbation_rate"].mean()),
                                float(g["similarity"].mean())))
            skipped = a[a["counted"] != True]       # noqa: E712
            if len(skipped):
                lines.append("| %s | %s | (excluded: original not malicious) | %d | - | - | - | - | - |"
                             % (a["model"].iloc[0], a["mode"].iloc[0], len(skipped)))
        lines.append("")

    # ── cross-model transfer: also computed from the stored per-sample rows ──
    lines += ["## cross-model transfer", ""]
    tr_path = os.path.join(ROOT, "results", "transfer_matrix.csv")
    if not os.path.exists(tr_path):
        lines += ["no transfer matrix: src/run_transfer.py did not finish "
                  "(see the log above).", ""]
    else:
        tr = pd.read_csv(tr_path)
        lines += ["`flipped_source` = only perturbations that fooled the source "
                  "model (the classic matrix, small n); `applied` = every "
                  "perturbation the source applied, with the TARGET's own "
                  "caught originals as the denominator.",
                  "| subset | source | target | mode | task | candidates | caught | flips | ASR | 95% CI |",
                  "|---|---|---|---|---|---|---|---|---|---|"]
        for _, r in tr.sort_values(["subset", "mode", "task", "source", "target"]).iterrows():
            lines.append("| %s | %s | %s | %s | %s | %d | %d | %d | %.1f%% | %.1f-%.1f%% |"
                         % (r["subset"], r["source"], r["target"], r["mode"],
                            r["task"], int(r["n_candidates"]),
                            int(r["n_target_caught"]), int(r["n_flips"]),
                            100.0 * r["transfer_asr"],
                            100.0 * r["ci95_low"], 100.0 * r["ci95_high"]))
        lines.append("")
        # The diagonal is the only check that says the replay path is faithful:
        # a model's own perturbations re-sent must reproduce its attack. Reported
        # before the off-diagonal cells so a broken diagonal is visible in the
        # first screen of the report, not inferred from a suspiciously low rate.
        diag = tr[(tr["subset"] == "applied") & (tr["source"] == tr["target"])]
        if not len(diag):
            lines += ["self-replay: **NOT RUN** - no target was replayed with "
                      "its own perturbations (`--include-self`), so the "
                      "off-diagonal cells are unvalidated.", ""]
        else:
            atk_path = os.path.join(ROOT, "results", "attack_table.csv")
            mism = []
            if os.path.exists(atk_path):
                atk = pd.read_csv(atk_path)
                for _, r in diag.iterrows():
                    m = atk[(atk["model"] == r["source"])
                            & (atk["mode"] == r["mode"])
                            & (atk["task"] == r["task"])]
                    if len(m) and int(m["n_flips"].iloc[0]) != int(r["n_flips"]):
                        mism.append("%s/%s/%s: attack %d, replay %d"
                                    % (r["source"], r["mode"], r["task"],
                                       int(m["n_flips"].iloc[0]), int(r["n_flips"])))
            lines += ["self-replay: %d cell(s) covering %d replayed rows, %s."
                      % (len(diag), int(diag["n_candidates"].sum()),
                         "every flip count matches the attack run"
                         if not mism else "**MISMATCH**: " + "; ".join(mism[:4])),
                      ""]

    # ── saliency: did the probability route and the generation route agree? ──
    ver_path = os.path.join(ROOT, "results", "saliency_verification.csv")
    if os.path.exists(ver_path):
        ver = pd.read_csv(ver_path)
        lines += ["## saliency verdict-channel check", "",
                  "The saliency attack decides success on P(malicious) < 0.5; "
                  "every other mode uses the generated verdict. Both counts are "
                  "shown because a gap between them is a result about the "
                  "measurement, not a bug.",
                  "| model | task | n | flips (prob) | flips (gen) | agree | prob-only | gen-only |",
                  "|---|---|---|---|---|---|---|---|"]
        for _, r in ver.iterrows():
            lines.append("| %s | %s | %d | %d | %d | %d | %d | %d |"
                         % (r["model"], r["task"], r["n"], r["flips_prob"],
                            r["flips_gen"], r["agree"], r["prob_only"],
                            r["gen_only"]))
        lines.append("")

    # ── defences: the ASR only means something next to its operating point ──
    thr_path = os.path.join(ROOT, "results", "defense_thresholds.csv")
    if os.path.exists(thr_path):
        thr = pd.read_csv(thr_path)
        lines += ["## defence operating points", "",
                  "tau is fitted on clean benign mail to the stated FPR budget; "
                  "clean TPR is what the filter costs.",
                  "| model | task | tau | FPR @0.5 | FPR @tau | TPR @0.5 | TPR @tau | budget met |",
                  "|---|---|---|---|---|---|---|---|"]
        for _, r in thr.iterrows():
            lines.append("| %s | %s | %.4f | %.3f | %.3f | %.3f | %.3f | %s |"
                         % (r["model"], r["task"], r["tau"], r["fpr_at_0.5"],
                            r["fpr_at_tau"], r["tpr_at_0.5"], r["tpr_at_tau"],
                            bool(r["budget_met"])))
        lines.append("")

    lines += ["## files", "```"]
    for rel in ("results/eval_subset.csv", "results/attack_eligible.csv",
                "results/clean_baseline_results.csv", "results/baseline_table.csv"):
        path = os.path.join(ROOT, rel)
        lines.append("%-45s %s" % (rel, "%d bytes" % os.path.getsize(path)
                                   if os.path.exists(path) else "MISSING"))
    # Add attack results if available
    for path in sorted(glob.glob(os.path.join(ROOT, "results", "attack_*.csv"))) \
            + sorted(glob.glob(os.path.join(ROOT, "results", "asr_summary_*.txt"))):
        rel = os.path.relpath(path, ROOT).replace(os.sep, "/")
        lines.append("%-55s %d bytes" % (rel, os.path.getsize(path)))
    lines.append("```")
    with open(os.path.join(ROOT, "REPORT.md"), "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    log("wrote REPORT.md")


main()
